sp_widget.client_script:
/*
  Bulk Review Date Update — Client Script v5.1
  - NEW: Depot filter, cascading Zone -> Region -> Depot
  - Auto-poll treats Processing as in-flight
*/
api.controller = function($scope, $timeout, $q) {
  var c = this;

  var emptyFilters = function() {
    return { search: '', segment: '', zone: '', region: '', depot: '', review: '', change: '' };
  };

  c.filters = emptyFilters();
  c.pageSizes = [10, 15, 25, 50];
  c.pageSize = 15;
  c.page = (c.data && c.data.page) || 1;
  c.pageInput = c.page;
  c.customers = (c.data && c.data.customers) || [];
  c.total = (c.data && c.data.total) || 0;

  c.sel = {};
  c.dates = {};
  c.bulkDate = null;

  c.loading = false;
  c.loadingPage = false;
  c.selectingAll = false;
  c.submitted = false;
  c.triedSubmit = false;
  c.resultMessage = '';
  c.validationMsg = '';
  c.progress = '';

  c.history = [];
  c.historyLoaded = false;
  c.failedCount = 0;

  c.retrying = {};        // queueId -> true while a retry is in flight
  c.retryingAll = false;
  c.retryMsg = '';
  c.refreshing = false;

  var reqId = 0;
  var searchTimer = null;
  var pollTimer = null;

  function toYMD(d) {
    if (!d) return '';
    if (typeof d === 'string') return d;
    var m = d.getUTCMonth() + 1, day = d.getUTCDate();
    return d.getUTCFullYear() + '-' + (m < 10 ? '0' + m : m) + '-' + (day < 10 ? '0' + day : day);
  }

  /* ---------- Filter dropdown options ---------- */
  function combos() { return (c.data && c.data.options) || []; }

  function distinct(list, key) {
    var seen = {}, out = [];
    for (var i = 0; i < list.length; i++) {
      var v = list[i][key];
      if (v && !seen[v]) { seen[v] = true; out.push(v); }
    }
    return out.sort();
  }

  c.segments = function() { return distinct(combos(), 'segment'); };
  c.zoneList = function() { return distinct(combos(), 'zone'); };

  c.regionList = function() {
    var list = combos();
    if (c.filters.zone) list = list.filter(function(o) { return o.zone === c.filters.zone; });
    return distinct(list, 'region');
  };

  // depots narrow by the chosen zone and region (and segment, if set)
  c.depotList = function() {
    var f = c.filters;
    var list = combos().filter(function(o) {
      return (!f.zone || o.zone === f.zone) &&
             (!f.region || o.region === f.region) &&
             (!f.segment || o.segment === f.segment);
    });
    return distinct(list, 'depot');
  };

  /* ---------- Paging ---------- */
  c.totalPages = function() { return Math.max(Math.ceil(c.total / c.pageSize), 1); };
  c.rangeFrom = function() { return c.total === 0 ? 0 : (c.page - 1) * c.pageSize + 1; };
  c.rangeTo = function() { return Math.min(c.page * c.pageSize, c.total); };

  function fetchPage() {
    var myReq = ++reqId;
    c.loadingPage = true;
    c.server.get({
      action: 'page',
      page: c.page,
      pageSize: c.pageSize,
      filters: c.filters
    }).then(function(resp) {
      if (myReq !== reqId) return;
      c.customers = resp.data.customers || [];
      c.total = resp.data.total || 0;
      c.pageInput = c.page;
      c.loadingPage = false;
    }, function() {
      if (myReq !== reqId) return;
      c.loadingPage = false;
    });
  }

  c.goTo = function(p) {
    p = parseInt(p, 10);
    if (isNaN(p)) { c.pageInput = c.page; return; }
    p = Math.min(Math.max(p, 1), c.totalPages());
    if (p === c.page) { c.pageInput = c.page; return; }
    c.page = p;
    fetchPage();
  };

  /* ---------- Filters / search ---------- */
  c.applyFilters = function() {
    c.page = 1;
    fetchPage();
  };

  c.onSearch = function() {
    if (searchTimer) $timeout.cancel(searchTimer);
    searchTimer = $timeout(c.applyFilters, 400);
  };

  // drop a selected depot that no longer exists in the narrowed list
  function keepDepotValid() {
    if (c.filters.depot && c.depotList().indexOf(c.filters.depot) === -1) c.filters.depot = '';
  }

  c.onSegmentChange = function() {
    keepDepotValid();
    c.applyFilters();
  };

  c.onZoneChange = function() {
    c.filters.region = '';
    c.filters.depot = '';
    c.applyFilters();
  };

  c.onRegionChange = function() {
    c.filters.depot = '';
    c.applyFilters();
  };

  c.hasFilters = function() {
    var f = c.filters;
    return !!(f.search || f.segment || f.zone || f.region || f.depot || f.review || f.change);
  };

  c.clearFilters = function() {
    c.filters = emptyFilters();
    c.applyFilters();
  };

  c.filterFailed = function() {
    c.filters = emptyFilters();
    c.filters.change = 'Failed';
    c.applyFilters();
  };

  /* ---------- Selection (kept across pages) ---------- */
  c.isSel = function(row) { return !!c.sel[row.customerSysId]; };

  c.toggleRow = function(row) {
    var id = row.customerSysId;
    if (c.sel[id]) {
      delete c.sel[id];
    } else {
      c.sel[id] = {
        customerSysId: id,
        pan: row.pan,
        segment: row.segment,
        currentReviewDate: row.currentReviewDate
      };
    }
    c.validationMsg = '';
  };

  c.pageAllSelected = function() {
    if (!c.customers.length) return false;
    for (var i = 0; i < c.customers.length; i++) {
      if (!c.sel[c.customers[i].customerSysId]) return false;
    }
    return true;
  };

  c.togglePage = function() {
    var all = c.pageAllSelected();
    for (var i = 0; i < c.customers.length; i++) {
      var r = c.customers[i];
      if (all) delete c.sel[r.customerSysId];
      else if (!c.sel[r.customerSysId]) c.toggleRow(r);
    }
    c.validationMsg = '';
  };

  c.selectAllMatching = function() {
    c.selectingAll = true;
    c.server.get({ action: 'ids', filters: c.filters }).then(function(resp) {
      var list = (resp.data && resp.data.matching) || [];
      for (var i = 0; i < list.length; i++) {
        var r = list[i];
        if (!c.sel[r.customerSysId]) {
          c.sel[r.customerSysId] = {
            customerSysId: r.customerSysId,
            pan: r.pan,
            segment: r.segment,
            currentReviewDate: r.currentReviewDate
          };
        }
      }
      c.selectingAll = false;
    }, function() {
      c.selectingAll = false;
      c.validationMsg = 'Could not select all matching customers. Please try again.';
    });
  };

  c.clearSelection = function() {
    c.sel = {};
    c.dates = {};
    c.validationMsg = '';
  };

  c.onRowDate = function(row) {
    if (c.dates[row.customerSysId] && !c.sel[row.customerSysId]) c.toggleRow(row);
    c.validationMsg = '';
  };

  /* ---------- Counts ---------- */
  c.selectedCount = function() { return Object.keys(c.sel).length; };

  c.readyCount = function() {
    var n = 0;
    for (var id in c.sel) if (c.dates[id]) n++;
    return n;
  };

  c.missingCount = function() { return c.selectedCount() - c.readyCount(); };

  c.applyDateToSelected = function() {
    if (!c.bulkDate) return;
    for (var id in c.sel) c.dates[id] = new Date(c.bulkDate.getTime());
    c.validationMsg = '';
  };

  /* ---------- Formatting + status helpers ---------- */
  c.formatINR = function(v) {
    var n = Math.abs(parseFloat(v));
    if (isNaN(n)) return '0';
    return n.toLocaleString('en-IN', { maximumFractionDigits: 2 });
  };

  function isInFlightStatus(s) { return s === 'Pending' || s === 'Processing'; }

  // Pending with attempts/errors means the job already tried and is retrying
  function isRetrying(e) {
    return e && e.status === 'Pending' && (e.attempts > 0 || e.connRetries > 0);
  }

  c.statusLabel = function(e) {
    if (!e) return '';
    if (isRetrying(e)) return 'Retrying';
    return e.status;
  };

  c.statusClass = function(e) {
    if (!e) return 'is-pending';
    if (e.status === 'Success') return 'is-success';
    if (e.status === 'Failed') return 'is-failed';
    return 'is-pending';
  };

  c.showAttempts = function(e) {
    return e && (e.status === 'Failed' || isRetrying(e));
  };

  c.showError = function(e) {
    return e && e.error && e.status !== 'Success';
  };

  c.shortErr = function(t) {
    t = String(t || '');
    return t.length > 90 ? t.substring(0, 90) + '…' : t;
  };

  /* ---------- Apply a retry / refresh response ---------- */
  function applyFresh(d) {
    if (!d) return;
    if (d.customers) { c.customers = d.customers; c.total = d.total || 0; }
    if (d.history)   { c.history = d.history; c.historyLoaded = true; }
    if (typeof d.failedCount !== 'undefined') c.failedCount = d.failedCount;
  }

  function hasInFlight() {
    var i;
    for (i = 0; i < c.customers.length; i++) {
      var lc = c.customers[i].lastChange;
      if (lc && isInFlightStatus(lc.status)) return true;
    }
    for (i = 0; i < c.history.length; i++) {
      if (isInFlightStatus(c.history[i].status)) return true;
    }
    return false;
  }

  /* ---------- History / refresh ---------- */
  c.loadHistory = function() {
    c.server.get({ action: 'history' }).then(function(resp) {
      c.history = (resp.data && resp.data.history) || [];
      c.failedCount = (resp.data && resp.data.failedCount) || 0;
      c.historyLoaded = true;
    }, function() {
      c.historyLoaded = true;
    });
  };

  // refresh history, then the current page
  function refreshQuiet() {
    return c.server.get({
      action: 'history'
    }).then(function(h) {
      c.history = (h.data && h.data.history) || [];
      c.failedCount = (h.data && h.data.failedCount) || 0;
      c.historyLoaded = true;
      return c.server.get({ action: 'page', page: c.page, pageSize: c.pageSize, filters: c.filters });
    }).then(function(p) {
      c.customers = (p.data && p.data.customers) || c.customers;
      c.total = (p.data && p.data.total) || c.total;
    });
  }

  c.refreshAll = function() {
    c.refreshing = true;
    refreshQuiet().finally(function() { c.refreshing = false; });
  };

  /* ---------- Retry (same pattern as View My Requests) ---------- */
  c.retryOne = function(entry) {
    if (!entry || c.retrying[entry.id]) return;
    if (!confirm('Retry the SAP update for ' + (entry.customerCode || 'this customer') + '?')) return;

    c.retrying[entry.id] = true;
    c.retryMsg = '';

    c.server.get({
      action: 'retry',
      queueId: entry.id,
      page: c.page,
      pageSize: c.pageSize,
      filters: c.filters
    }).then(function(resp) {
      delete c.retrying[entry.id];
      var d = resp.data || {};
      c.retryMsg = d.retry_result ? d.retry_result.message : '';
      applyFresh(d);
      if (d.retry_result && d.retry_result.ok) c.pollQueue(4);
    }, function() {
      delete c.retrying[entry.id];
      c.retryMsg = 'Could not submit the retry. Please try again.';
    });
  };

  c.retryAllFailed = function() {
    if (c.retryingAll || c.failedCount < 1) return;
    if (!confirm('Retry all ' + c.failedCount + ' failed update(s)?')) return;

    c.retryingAll = true;
    c.retryMsg = '';

    c.server.get({
      action: 'retry_failed',
      page: c.page,
      pageSize: c.pageSize,
      filters: c.filters
    }).then(function(resp) {
      c.retryingAll = false;
      var d = resp.data || {};
      c.retryMsg = d.retry_result ? d.retry_result.message : '';
      applyFresh(d);
      if (d.retry_result && d.retry_result.ok) c.pollQueue(4);
    }, function() {
      c.retryingAll = false;
      c.retryMsg = 'Could not submit the retry. Please try again.';
    });
  };

  // checks every 30 s, up to `tries` times, while something is still Pending/Processing
  c.pollQueue = function(tries) {
    if (pollTimer) $timeout.cancel(pollTimer);
    pollTimer = $timeout(function() {
      refreshQuiet().then(function() {
        if (hasInFlight() && tries > 1) c.pollQueue(tries - 1);
        else c.retryMsg = '';
      });
    }, 30000);
  };

  $scope.$on('$destroy', function() {
    if (pollTimer) $timeout.cancel(pollTimer);
    if (searchTimer) $timeout.cancel(searchTimer);
  });

  /* ---------- Submit (chunks of 500) ---------- */
  c.submit = function() {
    var selections = [], missing = 0;
    c.triedSubmit = true;
    c.validationMsg = '';

    for (var id in c.sel) {
      var s = c.sel[id];
      if (!c.dates[id]) { missing++; continue; }
      selections.push({
        customerSysId: s.customerSysId,
        pan: s.pan,
        segment: s.segment,
        oldReviewDate: s.currentReviewDate || '',
        newReviewDate: toYMD(c.dates[id])
      });
    }

    if (missing > 0) {
      c.validationMsg = missing + ' selected customer(s) have no new review date. Set a date or untick them (use "Apply to Selected" to set one date for all).';
      return;
    }
    if (selections.length === 0) return;

    var CHUNK = 500, chunks = [];
    for (var i = 0; i < selections.length; i += CHUNK) chunks.push(selections.slice(i, i + CHUNK));

    var done = 0, skipped = 0, sent = 0;
    c.loading = true;
    c.progress = '0/' + selections.length;

    var chain = $q.when();
    chunks.forEach(function(chunk) {
      chain = chain.then(function() {
        return c.server.get({ action: 'submit', selections: chunk }).then(function(resp) {
          done += (resp.data && resp.data.count) || 0;
          skipped += (resp.data && resp.data.skipped) || 0;
          sent += chunk.length;
          c.progress = sent + '/' + selections.length;
        });
      });
    });

    chain.then(function() {
      c.loading = false;
      c.resultMessage = done + ' review date update(s) submitted for processing.' +
        (skipped ? ' ' + skipped + ' skipped (not in your zone).' : '');
      c.submitted = true;
    }, function() {
      c.loading = false;
      c.validationMsg = 'Submission failed after ' + done + ' record(s). Please check "Recent Updates" before retrying.';
    });
  };

  /* ---------- New batch ---------- */
  c.reset = function() {
    c.sel = {};
    c.dates = {};
    c.bulkDate = null;
    c.triedSubmit = false;
    c.validationMsg = '';
    c.resultMessage = '';
    c.retryMsg = '';
    c.filters = emptyFilters();
    c.page = 1;
    c.submitted = false;
    fetchPage();
    c.loadHistory();
  };

  if (!(c.data && c.data.error)) c.loadHistory();
};

sp_widget.css:
/*
  Bulk Review Date Update — v2.1 (CLM design system)
  CHANGES vs v2.0 (top card only):
  - NEW page-header banner block (.clm-hero*): navy gradient tile with decorative arcs,
    yellow bar, white title + yellow accent, light subtitle, stat block (customer count)
  - Widget now sits on #eff3f7 with 24px 32px padding; the banner floats with a shadow and
    the section below has its own full border and 8px radius
  - Removed: .clm-brd-header, .clm-brd-header-left/-meta, .clm-brd-title, .clm-brd-subtitle,
    .clm-chip-dark (no longer used)
  v2.0:
  - Numbered section, yellow-marker cards, chips
  - Factor tiles for the summary, light-header table with tinted group row
  - Result row with submit, missing-date highlights
  - Responsive: tiles 2 per row ≤1100px, table → label/value cards ≤768px, stack ≤640px
  - Widget prefix: clm-brd-  |  Font rule kept LAST
*/
@import url('https://fonts.googleapis.com/css2?family=Oxygen:wght@300;400;700&display=swap');

.clm-brd { background:#eff3f7; padding:24px 32px; margin-bottom:24px; color:#1a1a1a; box-sizing:border-box; }

/* ============================================================
   PAGE HEADER BANNER (top card) — v2.1 (red/orange theme)
   ============================================================ */
.clm-hero {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 20px 32px;
  padding: 28px 32px;
  margin-bottom: 20px;
  border-radius: 12px;
  background: linear-gradient(135deg, #9b1111 0%, #b81e1e 45%, #e0301e 100%);
  color: #ffffff;
  box-shadow: 0 10px 28px rgba(120, 20, 15, 0.28);
  box-sizing: border-box;
}
.clm-hero::before,
.clm-hero::after { content: ""; position: absolute; border-radius: 50%; pointer-events: none; }
.clm-hero::before { width: 360px; height: 360px; right: -110px; top: -190px; background: rgba(244, 123, 48, 0.55); }
.clm-hero::after  { width: 260px; height: 260px; right: 160px; bottom: -200px; background: rgba(120, 15, 15, 0.45); }
.clm-hero-left, .clm-hero-right { position: relative; z-index: 1; }
.clm-hero-left { flex: 1 1 380px; min-width: 0; }

.clm-hero-bar { width: 44px; height: 6px; margin-bottom: 12px; border-radius: 3px; background: #fff200; }
.clm-hero-title { margin: 0; font-size: 26px; font-weight: 700; line-height: 1.25; color: #ffffff; }
.clm-hero-accent { color: #fff200; }
.clm-hero-sub { max-width: 720px; margin-top: 6px; font-size: 15px; font-weight: 400; line-height: 1.5; color: #ffeae4; }

.clm-hero-right { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }
.clm-hero-stat { padding-left: 24px; border-left: 1px solid rgba(255, 255, 255, 0.3); text-align: right; }
.clm-hero-stat-v { font-size: 34px; font-weight: 700; line-height: 1.1; letter-spacing: 1px; color: #fff200; white-space: nowrap; text-shadow: 0 1px 3px rgba(80, 10, 10, 0.35); }
.clm-hero-stat-k { margin-top: 6px; font-size: 12px; font-weight: 700; letter-spacing: 0.6px; text-transform: uppercase; color: #ffd9cf; white-space: nowrap; }
/* ---------- Section ---------- */
.clm-section { background:#fff; border:1px solid #e0e6ed; border-top:none; padding:28px 32px; }
.clm-brd > .clm-section { border-top:1px solid #e0e6ed; border-radius:8px; box-shadow:0 4px 16px rgba(0,0,0,.04); }
.clm-section-title { display:flex; align-items:center; gap:12px; margin-bottom:20px;
  font-size:14px; font-weight:700; color:#1a1a1a; text-transform:uppercase; letter-spacing:1px; }
.clm-section-num { width:26px; height:26px; border-radius:50%; background:#F3D54E; color:#1a1a1a; flex-shrink:0;
  font-size:13px; font-weight:700; display:inline-flex; align-items:center; justify-content:center; }

/* ---------- Card ---------- */
.clm-block { margin-top:16px; background:#fff; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
.clm-block-head { display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:14px 20px; background:#fafbfc; border-bottom:1px solid #dde3ea; }
.clm-block-title { display:flex; align-items:center; gap:10px; font-size:13px; font-weight:700; color:#1a1a1a;
  text-transform:uppercase; letter-spacing:.8px; }
.clm-block-title::before { content:""; width:4px; height:16px; border-radius:2px; background:#F3D54E; flex-shrink:0; }
.clm-block-sub { margin:4px 0 0 14px; font-size:12px; color:#5a6a7a; }
.clm-block-meta { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.clm-chip { display:inline-flex; align-items:center; gap:6px; padding:4px 10px; background:#fff;
  border:1px solid #dde3ea; border-radius:12px; font-size:12px; font-weight:700; color:#1a1a1a; white-space:nowrap; }
.clm-chip-k { font-weight:400; color:#5a6a7a; }
.clm-chip-live { background:#eaf7ee; border-color:#b9e3c6; color:#1e8449; }
.clm-chip-req  { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }
.clm-chip-req .clm-chip-k { color:#7a5a00; }
.clm-tw-body { padding:18px 20px; }

.clm-block-dev { border-color:#f3c2bc; }
.clm-block-dev .clm-block-head { background:#fef5f4; border-bottom-color:#f6d5d0; }
.clm-block-dev .clm-block-title { color:#b3261e; }
.clm-block-dev .clm-block-title::before { background:#E23D28; }

/* ---------- Summary tiles ---------- */
.clm-brd-tiles { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:12px; }
.clm-tw-factor { padding:12px 14px; border:1px solid #e0e6ed; border-radius:6px; background:#fafbfc; }
.clm-tw-factor-k { font-size:12px; color:#5a6a7a; margin-bottom:4px; }
.clm-tw-factor-v { font-size:20px; font-weight:700; color:#1a1a1a; white-space:nowrap; }
.clm-tw-factor-s { font-size:11px; color:#7f8c9a; margin-top:4px; }
.clm-tw-factor.is-sel { background:#fffcf0; border-color:#f1e2a0; }
.clm-tw-factor.is-ok  { background:#f4fbf6; border-color:#cfead8; }
.clm-tw-factor.is-ok  .clm-tw-factor-v { color:#1e8449; }
.clm-tw-factor.is-bad { background:#fef5f4; border-color:#f5c2bc; }
.clm-tw-factor.is-bad .clm-tw-factor-v { color:#c0392b; }

/* ---------- Search & bulk apply ---------- */
.clm-brd-filters { display:grid; grid-template-columns:2fr 1fr auto; gap:16px; align-items:end; }
.clm-brd-field { display:flex; flex-direction:column; gap:6px; min-width:0; }
.clm-brd-label { margin:0; font-size:12px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-brd-link { background:none; border:none; padding:4px 6px; font-size:12px; font-weight:700; color:#AF272F; cursor:pointer; }
.clm-brd-link:hover { text-decoration:underline; }

/* ---------- Inputs & buttons ---------- */
.clm-input { width:100%; height:38px; padding:8px 12px; border:1px solid #cdd4dc; border-radius:6px; background:#fff;
  font-size:13px; color:#1a1a1a; outline:none; transition:border-color .2s, box-shadow .2s; }
.clm-input:focus { border-color:#E87722; box-shadow:0 0 0 3px rgba(232,119,34,.12); }
.clm-btn { display:inline-flex; align-items:center; justify-content:center; gap:8px; height:38px; padding:0 18px;
  border:1px solid transparent; border-radius:6px; font-size:13px; font-weight:700; cursor:pointer;
  white-space:nowrap; transition:all .2s; }
.clm-btn:disabled { opacity:.5; cursor:not-allowed; }
.clm-btn-outline { background:#fff; border-color:#cdd4dc; color:#1a1a1a; }
.clm-btn-outline:not(:disabled):hover { background:#1a1a1a; border-color:#1a1a1a; color:#F3D54E; }
.clm-btn-primary { background:#E87722; color:#fff; }
.clm-btn-primary:not(:disabled):hover { background:#d35400; }
.clm-checkbox { width:16px; height:16px; margin:0; cursor:pointer; accent-color:#E87722; vertical-align:middle; }

/* ---------- Table ---------- */
.clm-table-wrap { overflow-x:auto; background:#fff; }
.clm-brd-table-wrap { max-height:560px; overflow-y:auto; }
.clm-table { width:100%; border-collapse:collapse; font-size:13px; font-variant-numeric:tabular-nums; }
.clm-table th { background:#eef1f5; color:#2b3440; padding:12px 14px; font-size:12px; font-weight:700;
  text-transform:uppercase; letter-spacing:.6px; text-align:center; white-space:nowrap; border:1px solid #dde3ea; }
.clm-table td { padding:12px 14px; color:#1a1a1a; text-align:center; white-space:nowrap; border:1px solid #e6eaef; vertical-align:middle; }
.clm-table tr > :first-child { border-left:0; }
.clm-table tr > :last-child  { border-right:0; }
.clm-table thead tr:first-child th { border-top:0; }
.clm-table tbody tr:last-child td  { border-bottom:0; }
.clm-table .grp { border-left:2px solid #c9d1db !important; }
.clm-table tr.super th { letter-spacing:1px; padding:10px 14px; }
.clm-table th.bg-blank { background:#f7f8fa; }
.clm-table th.bg-code  { background:#e3eefa; color:#0b5394; }
.clm-table th.bg-seg   { background:#f1f3f7; color:#3a4451; }
.clm-table th.bg-req   { background:#e6f4ea; color:#2e7d32; }

.clm-brd-table thead { position:sticky; top:0; z-index:2; }
.clm-brd-col-check { width:44px; text-align:center !important; }
.clm-brd-th-left, .clm-brd-td-left { text-align:left !important; }
.clm-brd-num { text-align:right !important; }
.clm-brd-table tbody tr { cursor:pointer; transition:background-color .15s; }
.clm-brd-table tbody tr:hover td { background:#fafbfc; }
.clm-brd-table tbody tr.is-selected td { background:#fffcf0; }
.clm-brd-table tbody tr.is-selected td:first-child { box-shadow:inset 4px 0 0 #F3D54E; }
.clm-brd-table tbody tr.clm-brd-empty-row { cursor:default; }

.clm-cust-name { font-weight:700; color:#1a1a1a; white-space:normal; min-width:180px; }
.clm-cust-code { margin-top:2px; font-size:12px; font-weight:600; color:#5a6a7a; }
.clm-brd-mono { font-family:"SFMono-Regular", Consolas, monospace !important; font-size:12.5px; letter-spacing:.3px; color:#3a4451; }
.clm-brd-tag { display:inline-block; margin:1px 2px; padding:2px 8px; border:1px solid #d6dbe1; border-radius:4px;
  background:#f5f6f8; font-size:11px; font-weight:700; color:#3a4451; text-transform:uppercase; }
.clm-brd-tag-seg { background:#eef6fb; border-color:#bae3ff; color:#1782c5; }
.clm-brd-muted { color:#a0aab6; font-style:italic; }
.clm-brd-date { width:150px; height:34px; padding:5px 10px; cursor:text; }
.clm-brd-date.is-missing { border-color:#f3d54e; background:#fffdf3; }
.clm-brd-date.is-error   { border-color:#E23D28; background:#fef5f4; }
.clm-brd-empty { padding:32px !important; text-align:center !important; color:#7f8c9a; }

/* ---------- Result row ---------- */
.clm-tw-res { display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  padding:16px 20px; background:#fffcf0; border-top:1px solid #f1e2a0; }
.clm-tw-res-k { font-size:13px; font-weight:700; color:#3a4451; text-transform:uppercase; letter-spacing:.6px; }
.clm-tw-res-f { margin-top:3px; font-size:12px; color:#7f8c9a; }
.clm-tw-res-v { font-size:30px; font-weight:700; line-height:1.1; color:#1a1a1a; }
.clm-tw-res.is-ok { background:#f4fbf6; border-top-color:#b9e3c6; }
.clm-tw-res.is-ok .clm-tw-res-v { color:#1e8449; }
.clm-brd-res-right { display:flex; align-items:center; gap:20px; margin-left:auto; }
.clm-brd-error { margin-top:6px; font-size:12px; font-weight:700; color:#c0392b; }

/* ---------- Error / success states ---------- */
.clm-brd-state { display:flex; flex-direction:column; align-items:center; gap:14px; padding:44px 20px; text-align:center; }
.clm-brd-state-icon { width:52px; height:52px; border-radius:50%; display:flex; align-items:center; justify-content:center;
  font-size:24px; font-weight:700; }
.clm-brd-state-icon.is-ok  { background:#eaf7ee; color:#1e8449; border:1px solid #b9e3c6; }
.clm-brd-state-icon.is-bad { background:#fdecea; color:#b3261e; border:1px solid #f5c2bc; }
.clm-brd-state-text { max-width:520px; font-size:14px; color:#3a4451; }

/* ---------- Responsive ---------- */
@media (max-width:1100px) {
  .clm-brd-tiles { grid-template-columns:repeat(2,minmax(0,1fr)); }
}
@media (max-width:1024px) {
  .clm-brd { padding:20px 24px; }
  .clm-hero { padding:24px 26px; }
}
@media (max-width:768px) {
  /* Page + banner */
  .clm-brd { padding:16px; }
  .clm-hero { padding:22px 20px; margin-bottom:16px; }
  .clm-hero::before { width:260px; height:260px; right:-110px; top:-150px; }
  .clm-hero::after  { display:none; }
  .clm-hero-title { font-size:22px; }
  .clm-hero-sub { font-size:14px; }
  .clm-hero-stat-v { font-size:28px; }

  .clm-section { padding-left:16px; padding-right:16px; }
  .clm-brd-filters { grid-template-columns:1fr 1fr; }
  .clm-brd-filters .clm-brd-field:first-child { grid-column:1 / -1; }
  .clm-brd-table-wrap { max-height:none; overflow:visible; }
  .clm-brd-table thead tr.super { display:none; }
  .clm-brd-table thead tr:not(.super) { display:flex; align-items:center; padding:8px 12px; background:#eef1f5; }
  .clm-brd-table thead tr:not(.super) th { display:none; }
  .clm-brd-table thead tr:not(.super) th.clm-brd-col-check { display:block; width:auto; padding:0; border:0; background:none; }
  .clm-brd-table thead tr:not(.super) th.clm-brd-col-check::after { content:"Select all shown"; margin-left:8px; }
  .clm-brd-table, .clm-brd-table thead, .clm-brd-table tbody { display:block; }
  .clm-brd-table .grp { border-left:0 !important; }
  .clm-brd-table tbody tr { display:block; position:relative; margin:10px; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
  .clm-brd-table tbody td { display:flex; justify-content:space-between; align-items:center; gap:12px;
    padding:9px 12px; border:0 !important; border-bottom:1px solid #eef1f5 !important; text-align:right !important; white-space:normal; }
  .clm-brd-table tbody td::before { content:attr(data-label); font-size:12px; color:#5a6a7a; text-align:left; }
  .clm-brd-table tbody td.clm-brd-col-check { position:absolute; top:4px; right:0; width:auto; border:0 !important; background:transparent !important; box-shadow:none !important; }
  .clm-brd-table tbody td.clm-brd-col-check::before { display:none; }
  .clm-brd-table tbody td.clm-brd-td-left { display:block; padding-right:44px; text-align:left !important; background:#fafbfc; }
  .clm-brd-table tbody td.clm-brd-td-left::before { display:none; }
  .clm-brd-table tbody tr.is-selected { border-color:#F3D54E; }
  .clm-brd-table tbody tr:last-child td { border-bottom:1px solid #eef1f5 !important; }
  .clm-brd-table tbody tr td:last-child { border-bottom:0 !important; }
  .clm-brd-table tbody tr.clm-brd-empty-row { border:0; }
  .clm-brd-table tbody tr.clm-brd-empty-row td { display:block; text-align:center !important; }
  .clm-brd-table tbody tr.clm-brd-empty-row td::before { display:none; }
  .clm-cust-name { min-width:0; }
}
@media (max-width:640px) {
  /* Banner stacks */
  .clm-hero { flex-direction:column; align-items:stretch; gap:16px; }
  .clm-hero-left { flex-basis:auto; width:100%; }
  .clm-hero-title { font-size:20px; }
  .clm-hero-sub { font-size:13px; }
  .clm-hero-right { width:100%; padding-top:14px; border-top:1px solid rgba(255,255,255,.22); }
  .clm-hero-stat { padding-left:0; border-left:0; text-align:left; }
  .clm-hero-stat-v { font-size:26px; }

  .clm-brd-filters { grid-template-columns:1fr; }
  .clm-brd-field-btn .clm-btn { width:100%; }
  .clm-tw-res-v { font-size:24px; }
  .clm-brd-res-right { width:100%; justify-content:space-between; }
  .clm-brd-date { width:150px; }
}
@media (max-width:480px) {
  .clm-brd { padding:12px 10px; }
  .clm-hero { padding:18px 16px; border-radius:10px; margin-bottom:12px; }
  .clm-hero-bar { width:36px; height:5px; margin-bottom:10px; }
  .clm-hero-stat-k { font-size:11px; }
}
@media (max-width:360px) {
  .clm-hero { padding:16px 14px; }
  .clm-hero-title { font-size:18px; }
  .clm-hero-sub { font-size:12px; }
  .clm-hero-stat-v { font-size:22px; }
}

/* ============================================================
   v3.0 — History: Last Change column, status chips, Recent Updates
   ============================================================ */
.clm-brd-check-inline { display:inline-flex; align-items:center; gap:8px; margin-top:14px;
  font-size:13px; font-weight:700; color:#3a4451; cursor:pointer; }

.clm-brd-last { text-align:left; min-width:170px; }
.clm-brd-last-top { display:flex; align-items:center; gap:8px; font-weight:700; }
.clm-brd-last-sub { margin-top:3px; font-size:11px; color:#7f8c9a; }

.clm-brd-status { display:inline-block; padding:2px 8px; border-radius:10px; font-size:11px; font-weight:700;
  text-transform:uppercase; letter-spacing:.4px; border:1px solid transparent; }
.clm-brd-status.is-pending { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }
.clm-brd-status.is-success { background:#eaf7ee; border-color:#b9e3c6; color:#1e8449; }
.clm-brd-status.is-failed  { background:#fdecea; border-color:#f5c2bc; color:#b3261e; }

.clm-brd-hist-wrap { max-height:360px; overflow-y:auto; }
.clm-brd-hist thead { position:sticky; top:0; z-index:2; }

@media (max-width:768px) {
  .clm-brd-last { min-width:0; text-align:right; }
  .clm-brd-last-top { justify-content:flex-end; }

  /* history table -> label/value cards (same pattern as the main table) */
  .clm-brd-hist-wrap { max-height:none; overflow:visible; }
  .clm-brd-hist thead { display:none; }
  .clm-brd-hist, .clm-brd-hist tbody { display:block; }
  .clm-brd-hist tbody tr.clm-brd-hist-row { display:block; margin:10px; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td { display:flex; justify-content:space-between; align-items:center; gap:12px;
    padding:9px 12px; border:0 !important; border-bottom:1px solid #eef1f5 !important; text-align:right !important; white-space:normal; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td::before { content:attr(data-label); font-size:12px; color:#5a6a7a; text-align:left; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td.clm-brd-td-left { display:block; text-align:left !important; background:#fafbfc; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td.clm-brd-td-left::before { display:none; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td:last-child { border-bottom:0 !important; }
}
/* ============================================================
   v4.0 — Filters, pagination, select-all banner, loading bar
   ============================================================ */
.clm-brd-fgrid { display:grid; grid-template-columns:repeat(auto-fit,minmax(170px,1fr)); gap:14px 16px; align-items:end; }
.clm-brd-field-wide { grid-column:span 2; }
.clm-brd-bulkrow { margin-top:16px; padding-top:16px; border-top:1px dashed #dde3ea; grid-template-columns:minmax(200px,1fr) auto auto; }
select.clm-input { appearance:auto; padding-right:8px; cursor:pointer; }

.clm-brd-table-wrap { max-height:none; overflow-y:visible; }
.clm-brd-table-wrap.is-loading { opacity:.55; pointer-events:none; transition:opacity .15s; }

.clm-brd-loadbar { height:3px; background:transparent; overflow:hidden; position:relative; }
.clm-brd-loadbar.is-on { background:#f5ecc0; }
.clm-brd-loadbar.is-on::after { content:""; position:absolute; top:0; left:-40%; width:40%; height:100%;
  background:#E87722; animation:clmBrdSlide 1s infinite ease-in-out; }
@keyframes clmBrdSlide { 0% { left:-40%; } 100% { left:100%; } }

.clm-brd-banner { padding:10px 20px; background:#fff8e1; border-bottom:1px solid #f1e2a0; font-size:13px; color:#7a5a00; }
.clm-brd-banner.is-done { background:#f4fbf6; border-bottom-color:#cfead8; color:#1e8449; }
.clm-brd-banner .clm-brd-link { margin-left:6px; }
.clm-brd-link:disabled { opacity:.5; cursor:not-allowed; }

.clm-brd-pager { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px 20px;
  padding:12px 20px; border-top:1px solid #dde3ea; background:#fafbfc; font-size:13px; color:#3a4451; }
.clm-brd-pager-ctrl { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.clm-brd-pager-size { display:inline-flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:#5a6a7a; margin-right:8px; }
.clm-brd-pager-size .clm-input { width:70px; height:32px; padding:4px 6px; }
.clm-brd-pbtn { height:32px; padding:0 12px; }
.clm-brd-pager-page { display:inline-flex; align-items:center; gap:6px; margin:0 4px; }
.clm-brd-pager-input { width:64px; height:32px; padding:4px 6px; text-align:center; }

/* history + last change */
.clm-brd-last { text-align:left; min-width:170px; }
.clm-brd-last-top { display:flex; align-items:center; gap:8px; font-weight:700; }
.clm-brd-last-sub { margin-top:3px; font-size:11px; color:#7f8c9a; }
.clm-brd-status { display:inline-block; padding:2px 8px; border-radius:10px; font-size:11px; font-weight:700;
  text-transform:uppercase; letter-spacing:.4px; border:1px solid transparent; }
.clm-brd-status.is-pending { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }
.clm-brd-status.is-success { background:#eaf7ee; border-color:#b9e3c6; color:#1e8449; }
.clm-brd-status.is-failed  { background:#fdecea; border-color:#f5c2bc; color:#b3261e; }
.clm-brd-hist-wrap { max-height:360px; overflow-y:auto; }
.clm-brd-hist thead { position:sticky; top:0; z-index:2; }

@media (max-width:768px) {
  .clm-brd-field-wide { grid-column:1 / -1; }
  .clm-brd-bulkrow { grid-template-columns:1fr; }
  .clm-brd-pager { justify-content:center; }
  .clm-brd-last { min-width:0; text-align:right; }
  .clm-brd-last-top { justify-content:flex-end; }

  .clm-brd-hist-wrap { max-height:none; overflow:visible; }
  .clm-brd-hist thead { display:none; }
  .clm-brd-hist, .clm-brd-hist tbody { display:block; }
  .clm-brd-hist tbody tr.clm-brd-hist-row { display:block; margin:10px; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td { display:flex; justify-content:space-between; align-items:center; gap:12px;
    padding:9px 12px; border:0 !important; border-bottom:1px solid #eef1f5 !important; text-align:right !important; white-space:normal; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td::before { content:attr(data-label); font-size:12px; color:#5a6a7a; text-align:left; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td.clm-brd-td-left { display:block; text-align:left !important; background:#fafbfc; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td.clm-brd-td-left::before { display:none; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td:last-child { border-bottom:0 !important; }
}
/* ============================================================
   v5.0 — Retry, attempts, error text, failed alert
   ============================================================ */
.clm-brd-retry-btn { background:#c0392b; color:#fff; height:36px; padding:0 16px; }
.clm-brd-retry-btn:not(:disabled):hover { background:#a93226; }
.clm-brd-retry-sm { height:28px; padding:0 12px; font-size:12px; margin-top:6px; }
.clm-block-meta .clm-brd-retry-sm { margin-top:0; }

.clm-brd-alert { display:flex; align-items:center; justify-content:space-between; gap:12px 20px; flex-wrap:wrap;
  margin-bottom:16px; padding:12px 16px; background:#fef5f4; border:1px solid #f5c2bc; border-left:4px solid #E23D28;
  border-radius:6px; font-size:13px; color:#1a1a1a; }
.clm-brd-alert-sub { display:block; margin-top:2px; font-size:12px; color:#5a6a7a; }
.clm-brd-alert-btns { display:flex; align-items:center; gap:12px; }
.clm-brd-note { margin:-6px 0 14px; font-size:12px; font-weight:700; color:#5a6a7a; }

.clm-brd-att { padding:1px 6px; border-radius:4px; background:#eef1f5; border:1px solid #dde3ea;
  font-size:10px; font-weight:700; color:#3a4451; }
.clm-brd-last-err { margin-top:4px; max-width:240px; font-size:11px; line-height:1.35; color:#b3261e; white-space:normal; word-break:break-word; }
.clm-brd-err-cell { max-width:260px; white-space:normal !important; font-size:12px; color:#b3261e; word-break:break-word; }

/* last change + status + history */
.clm-brd-last { text-align:left; min-width:190px; }
.clm-brd-last-top { display:flex; align-items:center; gap:8px; font-weight:700; flex-wrap:wrap; }
.clm-brd-last-sub { margin-top:3px; font-size:11px; color:#7f8c9a; }
.clm-brd-status { display:inline-block; padding:2px 8px; border-radius:10px; font-size:11px; font-weight:700;
  text-transform:uppercase; letter-spacing:.4px; border:1px solid transparent; }
.clm-brd-status.is-pending { background:#fff8e1; border-color:#f3d54e; color:#7a5a00; }
.clm-brd-status.is-success { background:#eaf7ee; border-color:#b9e3c6; color:#1e8449; }
.clm-brd-status.is-failed  { background:#fdecea; border-color:#f5c2bc; color:#b3261e; }
.clm-brd-hist-wrap { max-height:360px; overflow-y:auto; }
.clm-brd-hist thead { position:sticky; top:0; z-index:2; }

@media (max-width:768px) {
  .clm-brd-last { min-width:0; text-align:right; }
  .clm-brd-last-top { justify-content:flex-end; }
  .clm-brd-last-err { max-width:none; }
  .clm-brd-alert { flex-direction:column; align-items:flex-start; }

  .clm-brd-hist-wrap { max-height:none; overflow:visible; }
  .clm-brd-hist thead { display:none; }
  .clm-brd-hist, .clm-brd-hist tbody { display:block; }
  .clm-brd-hist tbody tr.clm-brd-hist-row { display:block; margin:10px; border:1px solid #dde3ea; border-radius:8px; overflow:hidden; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td { display:flex; justify-content:space-between; align-items:center; gap:12px;
    padding:9px 12px; border:0 !important; border-bottom:1px solid #eef1f5 !important; text-align:right !important; white-space:normal; max-width:none; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td::before { content:attr(data-label); font-size:12px; color:#5a6a7a; text-align:left; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td.clm-brd-td-left { display:block; text-align:left !important; background:#fafbfc; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td.clm-brd-td-left::before { display:none; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td.clm-brd-err-cell { display:flex; text-align:right !important; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td.clm-brd-err-cell::before { display:inline; }
  .clm-brd-hist tbody tr.clm-brd-hist-row td:last-child { border-bottom:0 !important; }
}
/* ---------- One font family (keep LAST) ---------- */
.clm-widget, .clm-widget *, .clm-widget input, .clm-widget select,
.clm-widget textarea, .clm-widget button, .clm-widget table {
  font-family: "Oxygen", "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
}
.clm-widget .clm-brd-mono { font-family:"SFMono-Regular", Consolas, monospace !important; }

sp_widget.script:
/*
  Bulk Review Date Update — Server Script v5.1
  - NEW: Depot filter (options carry depot; buildCustomerGr filters on depot)
  - Depot returned on each row
  - "Pending / retrying" status filter also matches Processing
  - Credit limit / SD read from cr_limit and security_deposit (confirmed from the list view)
*/
(function() {
  var CUST  = 'x_birl3_clm_clm_customer_master1';
  var QUEUE = 'x_birl3_clm_clm_review_date_update_queue';
  var MAX_SELECT_ALL = 20000;
  var MAX_ATTEMPTS = 3;          // keep in sync with CLMReviewDateWriteback
  var RETRY_ALL_CAP = 500;
  var CG1_IN = 'T00,N01,N07,N00';

  data.error = '';
  data.customers = [];
  data.total = 0;
  data.maxAttempts = MAX_ATTEMPTS;

  var action = (input && input.action) ? input.action : 'load';

  // ---- Zones mapped to this ZCH ----
  var zones = [];
  var mapGr = new GlideRecord('x_birl3_clm_role_user_mapping');
  mapGr.addQuery('u_role', 'ZCH');
  mapGr.addQuery('u_user', gs.getUserID());
  mapGr.addQuery('u_active', 'true');
  mapGr.query();
  while (mapGr.next()) zones.push(mapGr.getValue('u_zone'));
  if (zones.length === 0) {
    data.error = 'No active ZCH zone mapping found for this user.';
    return;
  }

  // ---- Queue record -> plain object ----
  function entryFrom(q) {
    return {
      id: q.getUniqueValue(),
      customerSysId: q.getValue('customer_code'),
      customerCode: q.getDisplayValue('customer_code'),
      customerName: q.customer_code.customer_name.toString(),
      segment: q.getValue('segment'),
      oldDate: q.getValue('old_review_date') || '',
      newDate: q.getValue('new_review_date') || '',
      status: q.getValue('status'),
      error: q.getValue('last_error') || '',
      attempts: parseInt(q.getValue('u_attempt_count'), 10) || 0,
      connRetries: parseInt(q.getValue('connection_retry_count'), 10) || 0,
      requestedBy: q.getDisplayValue('requested_by'),
      requestedOn: q.getDisplayValue('requested_on'),
      canRetry: false
    };
  }

  // ---- Customer sys_ids that have queue entries (optionally for some statuses) ----
  function queueCustomerIds(statusList) {
    var ids = [];
    var ga = new GlideAggregate(QUEUE);
    ga.addQuery('customer_code.zone', 'IN', zones.join(','));
    if (statusList) ga.addQuery('status', 'IN', statusList);
    ga.groupBy('customer_code');
    ga.query();
    while (ga.next()) ids.push(ga.getValue('customer_code'));
    return ids;
  }

  // ---- Build the filtered customer query (not yet executed) ----
  function buildCustomerGr(f) {
    f = f || {};
    var zoneList = zones;
    if (f.zone && zones.indexOf(f.zone) > -1) zoneList = [f.zone];

    var gr = new GlideRecord(CUST);
    gr.addQuery('zone', 'IN', zoneList.join(','));
    gr.addQuery('cg1', 'IN', CG1_IN);
    gr.addQuery('is_active', 'true');

    if (f.segment) gr.addQuery('segment', f.segment);
    if (f.region)  gr.addQuery('region', f.region);
    if (f.depot)   gr.addQuery('depot', f.depot);

    if (f.search) {
      var s = String(f.search).trim();
      if (s) {
        var qc = gr.addQuery('customer_name', 'CONTAINS', s);
        qc.addOrCondition('customer_code_sap', 'STARTSWITH', s);
        qc.addOrCondition('pan', 'STARTSWITH', s);
      }
    }

    if (f.review) {
      var todayStr = new GlideDate().getValue();
      if (f.review === 'notset') {
        gr.addNullQuery('next_review_date');
      } else if (f.review === 'overdue') {
        gr.addQuery('next_review_date', '<', todayStr);
      } else if (f.review === 'due30') {
        var d30 = new GlideDate();
        d30.addDaysLocalTime(30);
        gr.addQuery('next_review_date', '>=', todayStr);
        gr.addQuery('next_review_date', '<=', d30.getValue());
      }
    }

    if (f.change === 'never') {
      var allIds = queueCustomerIds('');
      if (allIds.length) gr.addQuery('sys_id', 'NOT IN', allIds.join(','));
    } else if (f.change) {
      var st = '';
      if (f.change === 'Pending') st = 'Pending,Processing';
      else if (f.change !== 'changed') st = f.change;        // Success / Failed
      var ids = queueCustomerIds(st);
      if (ids.length) gr.addQuery('sys_id', 'IN', ids.join(','));
      else gr.addQuery('sys_id', '-1');
    }
    return gr;
  }

  // ---- One page of customers + total count ----
  function loadPage(f, page, size) {
    page = Math.max(parseInt(page, 10) || 1, 1);
    size = Math.min(Math.max(parseInt(size, 10) || 15, 5), 100);

    var gr = buildCustomerGr(f);

    var ga = new GlideAggregate(CUST);
    ga.addEncodedQuery(gr.getEncodedQuery());
    ga.addAggregate('COUNT');
    ga.query();
    data.total = ga.next() ? parseInt(ga.getAggregate('COUNT'), 10) : 0;

    gr.orderBy('customer_code_sap');
    var start = (page - 1) * size;
    gr.chooseWindow(start, start + size);
    gr.query();

    var rows = [], ids = [];
    while (gr.next()) {
      var sd = parseFloat(gr.getValue('security_deposit'));
      if (isNaN(sd)) sd = 0;
      var id = gr.getUniqueValue();
      ids.push(id);
      rows.push({
        customerSysId: id,
        customerCode: gr.getValue('customer_code_sap'),
        pan: gr.getValue('pan'),
        customerName: gr.getValue('customer_name'),
        segment: gr.getValue('segment'),
        zone: gr.getValue('zone'),
        region: gr.getValue('region'),
        depot: gr.getValue('depot'),
        currentLimit: gr.getValue('cr_limit'),
        activeSD: Math.abs(sd),
        currentReviewDate: gr.getValue('next_review_date') || '',
        lastChange: null
      });
    }

    // latest queue entry per customer, only for the customers on this page
    if (ids.length) {
      var last = {};
      var q = new GlideRecord(QUEUE);
      q.addQuery('customer_code', 'IN', ids.join(','));
      q.orderByDesc('requested_on');
      q.query();
      while (q.next()) {
        var cid = q.getValue('customer_code');
        if (!last[cid]) {
          var e = entryFrom(q);
          e.canRetry = (e.status === 'Failed');   // latest record, so nothing newer exists
          last[cid] = e;
        }
      }
      for (var i = 0; i < rows.length; i++) rows[i].lastChange = last[rows[i].customerSysId] || null;
    }

    data.customers = rows;
    data.page = page;
    data.pageSize = size;
  }

  // ---- Filter dropdown options (segment / zone / region / depot combos) ----
  function loadOptions() {
    var combos = [];
    var ga = new GlideAggregate(CUST);
    ga.addQuery('zone', 'IN', zones.join(','));
    ga.addQuery('cg1', 'IN', CG1_IN);
    ga.addQuery('is_active', 'true');
    ga.groupBy('segment');
    ga.groupBy('zone');
    ga.groupBy('region');
    ga.groupBy('depot');
    ga.query();
    while (ga.next()) {
      combos.push({
        segment: ga.getValue('segment') || '',
        zone: ga.getValue('zone') || '',
        region: ga.getValue('region') || '',
        depot: ga.getValue('depot') || ''
      });
    }
    data.options = combos;
  }

  // ---- Queue ids that are the LATEST record of their customer and Failed ----
  function retryableFailedIds() {
    var failedCust = {};
    var fq = new GlideRecord(QUEUE);
    fq.addQuery('status', 'Failed');
    fq.addQuery('customer_code.zone', 'IN', zones.join(','));
    fq.setLimit(5000);
    fq.query();
    while (fq.next()) failedCust[fq.getValue('customer_code')] = true;

    var custIds = Object.keys(failedCust);
    if (!custIds.length) return [];

    var seen = {}, out = [];
    var q = new GlideRecord(QUEUE);
    q.addQuery('customer_code', 'IN', custIds.join(','));
    q.orderByDesc('requested_on');
    q.query();
    while (q.next()) {
      var cid = q.getValue('customer_code');
      if (seen[cid]) continue;
      seen[cid] = true;
      if (q.getValue('status') === 'Failed') out.push(q.getUniqueValue());
    }
    return out;
  }

  // ---- Recent updates (last 50 in the ZCH's zones) + failed count ----
  function loadHistory() {
    data.history = [];
    var seen = {};
    var q = new GlideRecord(QUEUE);
    q.addQuery('customer_code.zone', 'IN', zones.join(','));
    q.orderByDesc('requested_on');
    q.setLimit(50);
    q.query();
    while (q.next()) {
      var e = entryFrom(q);
      e.canRetry = (e.status === 'Failed') && !seen[e.customerSysId];  // newest first, so first seen = latest
      seen[e.customerSysId] = true;
      data.history.push(e);
    }
    data.failedCount = retryableFailedIds().length;
  }

  // ---- "Select all N matching" ----
  function loadMatchingIds(f) {
    var gr = buildCustomerGr(f);
    gr.orderBy('customer_code_sap');
    gr.setLimit(MAX_SELECT_ALL);
    gr.query();
    var list = [];
    while (gr.next()) {
      list.push({
        customerSysId: gr.getUniqueValue(),
        customerCode: gr.getValue('customer_code_sap'),
        customerName: gr.getValue('customer_name'),
        pan: gr.getValue('pan'),
        segment: gr.getValue('segment'),
        currentReviewDate: gr.getValue('next_review_date') || ''
      });
    }
    data.matching = list;
  }

  // ---- Submit (client sends chunks of 500) ----
  function submitSelections() {
    var selections = input.selections || [];
    var count = 0, skipped = 0;
    var cust = new GlideRecord(CUST);
    for (var i = 0; i < selections.length; i++) {
      var s = selections[i];
      if (!cust.get(s.customerSysId) || zones.indexOf(cust.getValue('zone')) === -1) {
        skipped++;
        continue;
      }
      var gr = new GlideRecord(QUEUE);
      gr.initialize();
      gr.customer_code = s.customerSysId;
      gr.pan = s.pan;
      gr.segment = s.segment;
      gr.old_review_date = s.oldReviewDate;
      gr.new_review_date = s.newReviewDate;
      gr.requested_by = gs.getUserID();
      gr.requested_on = new GlideDateTime();
      gr.status = 'Pending';
      gr.u_attempt_count = 0;
      gr.insert();
      count++;
    }
    data.count = count;
    data.skipped = skipped;
  }

  // ---- RETRY ----
  function requeue(q) {
    q.setValue('status', 'Pending');
    q.setValue('u_attempt_count', 0);
    q.setValue('connection_retry_count', 0);
    q.setValue('last_error', 'Manual retry by ' + gs.getUserDisplayName() + ' at ' + new GlideDateTime().getDisplayValue());
    q.update();
  }

  // returns { ok, blocked, message }
  function retryOne(queueId) {
    var q = new GlideRecord(QUEUE);
    if (!queueId || !q.get(queueId)) return { ok: false, message: 'Update record not found.' };

    // security: customer must be in one of this ZCH's zones
    var cust = new GlideRecord(CUST);
    if (!cust.get(q.getValue('customer_code')) || zones.indexOf(cust.getValue('zone')) === -1) {
      return { ok: false, message: 'You are not allowed to retry this update.' };
    }
    if (q.getValue('status') !== 'Failed') {
      return { ok: false, message: 'Only failed updates can be retried.' };
    }

    // safety: never push an old date over a newer update for the same customer
    var newer = new GlideRecord(QUEUE);
    newer.addQuery('customer_code', q.getValue('customer_code'));
    newer.addQuery('requested_on', '>', q.getValue('requested_on'));
    newer.setLimit(1);
    newer.query();
    if (newer.hasNext()) {
      return { ok: false, blocked: true, message: 'A newer update exists for this customer, so this one cannot be retried.' };
    }

    requeue(q);
    return { ok: true, message: 'Retry submitted. The SAP update will be attempted again shortly.' };
  }

  function retryAllFailed() {
    var ids = retryableFailedIds();
    if (!ids.length) return { ok: false, message: 'No failed updates to retry.' };

    var done = 0;
    for (var i = 0; i < ids.length && done < RETRY_ALL_CAP; i++) {
      if (retryOne(ids[i]).ok) done++;
    }
    return done > 0
      ? { ok: true, count: done, message: done + ' update(s) submitted for retry. SAP will be attempted again shortly.' }
      : { ok: false, message: 'Nothing could be retried.' };
  }

  var f = (input && input.filters) || {};

  if (action === 'load') {
    loadOptions();
    loadPage({}, 1, 15);
  } else if (action === 'page') {
    loadPage(f, input.page, input.pageSize);
  } else if (action === 'ids') {
    loadMatchingIds(f);
  } else if (action === 'history') {
    loadHistory();
  } else if (action === 'submit') {
    submitSelections();
  } else if (action === 'retry' || action === 'retry_failed') {
    data.retry_result = (action === 'retry') ? retryOne(input.queueId) : retryAllFailed();
    // return fresh data in the same call (same pattern as View My Requests)
    loadPage(f, input.page, input.pageSize);
    loadHistory();
  }
})();
